import java.util.*;

class Solution {
    public int[] sortByOrder(int[] a, int[] order) {
        int[] cnt = new int[1001];
        for (int v : a) cnt[v]++;
        int[] res = new int[a.length];
        int k = 0;
        for (int b : order) {               // values of order first, in its order
            while (cnt[b] > 0) { res[k++] = b; cnt[b]--; }
        }
        for (int v = 0; v <= 1000; v++) {   // leftovers in increasing order
            while (cnt[v] > 0) { res[k++] = v; cnt[v]--; }
        }
        return res;
    }
}

