function sortByOrder(a, order) {
  const cnt = new Array(1001).fill(0); for (const v of a) cnt[v]++;
  const out = [];
  for (const b of order) { while (cnt[b] > 0) { out.push(b); cnt[b]--; } }
  for (let v = 0; v <= 1000; v++) while (cnt[v]-- > 0) out.push(v);
  return out;
}
